/* questions details for region "math", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("math.questions",{"questions":{
"q-chicken-rabbit-0":{"target":{"node":"chicken-rabbit","href":"../math/arithmetic/chicken-rabbit/#step2"},"prompts":[{"node":"chicken-rabbit","ask":{"zh":"先假设全是鸡，算出来的脚数和实际脚数差多少？这个差额从哪里来？","en":"Assume they are all chickens first — how many feet short are you, and where does that gap come from?"}},{"node":"slope","ask":{"zh":"每把一只鸡换成一只兔，脚数增加几只？差额除以这个数，得到的是什么？","en":"Each time you swap one chicken for one rabbit, how many more feet appear? What does the gap divided by that number give you?"}}],"reveal":{"zh":"差额来自兔子比鸡多的脚；每换一只多 2 只脚，所以差额÷2 就是兔子的只数，剩下的就是鸡。","en":"The gap comes from rabbits having more feet than chickens; each swap adds 2 feet, so gap ÷ 2 is the number of rabbits and the rest are chickens."},"source":"../math/arithmetic/chicken-rabbit/#step2","lesson":"chicken-rabbit"},
"q-circle-intro-0":{"target":{"node":"circle-intro","href":"../math/geometry/circle-intro/#step3"},"prompts":[{"node":"circle-intro","ask":{"zh":"量几个大小不同的圆，周长除以直径，结果有什么共同点？","en":"Measure circles of different sizes and divide each circumference by its diameter — what do the answers have in common?"}},{"node":"unit-circle","ask":{"zh":"半径是 1 的圆，周长是多少？这个结果和 π 有什么关系？","en":"For a circle of radius 1, what is the circumference, and how does that relate to π?"}}],"reveal":{"zh":"不管圆多大，周长÷直径总是一个固定数，就是 π；半径 1 的圆周长正好是 2π。","en":"No matter the size, circumference ÷ diameter is always the same constant, π; a radius-1 circle has circumference 2π."},"source":"../math/geometry/circle-intro/#step3","lesson":"circle-intro"},
"q-fractions-0":{"target":{"node":"fractions","href":"../math/arithmetic/fractions/#step4"},"prompts":[{"node":"fractions","ask":{"zh":"1/2 和 1/3 的格子一样大吗？不一样大的格子能直接数在一起吗？","en":"Are halves and thirds the same size? Can pieces of different sizes be counted together directly?"}},{"node":"real-number-line","ask":{"zh":"把 1/2、1/3 和 2/5 放到数轴上，2/5 比 1/2 大还是小？","en":"Place 1/2, 1/3 and 2/5 on the number line — is 2/5 bigger or smaller than 1/2?"}}],"reveal":{"zh":"分母不同，格子大小就不同，不能直接把分子、分母各自相加；2/5 甚至比 1/2 还小。先通分成六分之几：3/6 + 2/6 = 5/6。","en":"Different denominators mean different-sized pieces, so numerators and denominators cannot simply be added; 2/5 is even smaller than 1/2. Convert to sixths first: 3/6 + 2/6 = 5/6."},"source":"../math/arithmetic/fractions/#step4","lesson":"fractions"},
"q-intervals-fences-0":{"target":{"node":"intervals-fences","href":"../math/arithmetic/intervals-fences/#step2"},"prompts":[{"node":"intervals-fences","ask":{"zh":"一排树两端都种，棵数比段数多几？如果两端都不种呢？","en":"Plant a row of trees with both ends planted — how many more trees than gaps? What if neither end is planted?"}},{"node":"patterns-sequences","ask":{"zh":"每增加一段，棵数增加几棵？这个规律怎样写成第 n 段的公式？","en":"Each extra gap adds how many trees? How would you write that as a rule for the nth gap?"}}],"reveal":{"zh":"两端都种多 1 棵，只种一端不多不少，两端都不种少 1 棵；差一来自“段数”和“点数”数的不是同一样东西。","en":"Both ends planted gives one extra tree, one end planted gives equal counts, neither end planted gives one fewer — the off-by-one comes from counting gaps versus counting posts, two different things."},"source":"../math/arithmetic/intervals-fences/#step2","lesson":"intervals-fences"},
"q-patterns-sequences-0":{"target":{"node":"patterns-sequences","href":"../math/algebra/patterns-sequences/#step2"},"prompts":[{"node":"patterns-sequences","ask":{"zh":"火柴棒链每加一个图形，总数增加几根？这个增量变不变？","en":"Each new figure in the matchstick chain adds how many sticks? Does that step stay the same?"}},{"node":"slope","ask":{"zh":"总数 = 增量 × n + 起头，这里的“增量”在图上像不像一条直线的斜率？","en":"In total = step × n + starter, does the \"step\" behave like the slope of a straight line?"}}],"reveal":{"zh":"增量不变时，每一项都在前一项上加同一个数，所以总数 = 增量 × n + 起头，不用画到第 100 个也能算出来。","en":"With a constant step, each term just adds the same number to the previous one, so total = step × n + starter — the 100th term needs no drawing."},"source":"../math/algebra/patterns-sequences/#step2","lesson":"patterns-sequences"},
"q-perimeter-area-0":{"target":{"node":"perimeter-vs-area","href":"../math/geometry/perimeter-area/#step1"},"prompts":[{"node":"perimeter-vs-area","ask":{"zh":"24 米绳子围长方形，长从 1 米变到 6 米，面积怎样变？","en":"Fencing a rectangle with 24 m of rope, how does the area change as the length goes from 1 m to 6 m?"}},{"node":"area-model-multiplication","ask":{"zh":"面积数的是什么？为什么等于长 × 宽？","en":"What does area count, and why is it length × width?"}}],"reveal":{"zh":"不一定。周长量的是一圈的长度，面积数的是里面的方格；同样 24 米的周长，1 × 11 的长方形只有 11 平方米，6 × 6 的正方形有 36 平方米。","en":"Not necessarily. Perimeter measures the length around, area counts the squares inside; with the same 24 m perimeter a 1 × 11 rectangle holds only 11 m², while a 6 × 6 square holds 36 m²."},"source":"../math/geometry/perimeter-area/#step1","lesson":"perimeter-area"},
"q-place-value-0":{"target":{"node":"place-value","href":"../math/arithmetic/place-value/#step2"},"prompts":[{"node":"place-value","ask":{"zh":"在计数器上，一个珠子从个位移到十位，它表示的数变成几倍？","en":"On a counting frame, a bead moved from the ones place to the tens place is worth how many times more?"}},{"node":"patterns-sequences","ask":{"zh":"连续左移两位、三位，分别是乘几？这个规律和找规律里的“每次加同一个数”有什么不同？","en":"Sliding two places left, then three — multiply by what each time? How is this different from a pattern where you add the same number each step?"}}],"reveal":{"zh":"每左移一位大 10 倍，所以乘 10 就是全体数字左移一位，末尾补 0 占位；这是乘法规律，不是加法规律。","en":"Each place left is worth 10 times more, so times 10 slides every digit one place left with a 0 holding the end place — a multiplicative pattern, not an additive one."},"source":"../math/arithmetic/place-value/#step2","lesson":"place-value"},
"q-inequalities-0":{"target":{"node":"inequalities","href":"../math/algebra/inequalities/#step3"},"prompts":[{"node":"inequalities","ask":{"zh":"不等式两边同时加一个数，不等号方向变吗？同时乘一个正数呢？","en":"Add the same number to both sides of an inequality — does the sign change? What about multiplying both sides by a positive number?"}},{"node":"slope","ask":{"zh":"把不等式想成一条直线：乘负数相当于把直线怎样翻转？翻转后，原来大的那边跑到哪边去了？","en":"Think of the inequality as a line — what does multiplying by a negative do to that line? After the flip, where does the side that was bigger end up?"}}],"reveal":{"zh":"加减和乘正数都不改变大小关系；乘负数相当于把数轴翻转，原来大的一边翻到了小的一边，所以不等号必须变向。","en":"Adding, subtracting and multiplying by a positive keep the order; multiplying by a negative flips the number line, so the side that was bigger lands on the smaller side — the sign must flip."},"source":"../math/algebra/inequalities/#step3","lesson":"inequalities"},
"q-inverse-proportion-0":{"target":{"node":"inverse-proportion","href":"../math/algebra/inverse-proportion/#step2"},"prompts":[{"node":"inverse-proportion","ask":{"zh":"x·y = k 不变时，x 变大，y 怎样变？画出来是直线还是曲线？","en":"With x·y = k fixed, when x grows, what happens to y? Does the graph come out straight or curved?"}},{"node":"slope","ask":{"zh":"正比例的图是一条过原点的直线，斜率是比值——反比例的“斜率”为什么不能这样看？","en":"Direct proportion graphs as a straight line through the origin whose slope is the ratio — why can't you read inverse proportion the same way?"}}],"reveal":{"zh":"乘积不变，一个变大另一个按比例变小，图像是双曲线；看 x·y 是否恒定就能区分正比例和反比例。","en":"With the product fixed, one growing means the other shrinks in proportion, and the graph is a hyperbola; checking whether x·y stays constant tells direct from inverse proportion."},"source":"../math/algebra/inverse-proportion/#step2","lesson":"inverse-proportion"},
"q-polygon-angles-0":{"target":{"node":"polygon-angles","href":"../math/geometry/polygon-angles/#step2"},"prompts":[{"node":"polygon-angles","ask":{"zh":"n 边形能分成几个三角形？每个三角形内角和是多少？","en":"Into how many triangles can an n-gon be split? What is each triangle's angle sum?"}},{"node":"unit-circle","ask":{"zh":"内角和是 (n−2)×180°，外角和是 360°——绕一圈转过的角度，为什么和边数无关？","en":"Interior sums to (n − 2) × 180° and exterior to 360° — why does the total turning around a full loop not depend on the number of sides?"}}],"reveal":{"zh":"从一个顶点连对角线，分成 n−2 个三角形，内角和就是 (n−2)×180°；外角是每步转过的角度，绕一圈总共转 360°，与边数无关。","en":"Diagonals from one vertex split it into n − 2 triangles, giving (n − 2) × 180°; each exterior angle is the turn at one step, and a full loop always turns 360°, whatever the number of sides."},"source":"../math/geometry/polygon-angles/#step2","lesson":"polygon-angles"},
"q-real-number-line-0":{"target":{"node":"real-number-line","href":"../math/arithmetic/real-number-line/#step2"},"prompts":[{"node":"real-number-line","ask":{"zh":"单位正方形的对角线有多长？这条线段能放到数轴上吗？","en":"How long is a unit square's diagonal? Can that length be placed on the number line?"}},{"node":"unit-circle","ask":{"zh":"√2 不能写成分数，小数不结束不循环——二分逼近是怎样一点点夹住它的？","en":"√2 is not a fraction and its decimals neither stop nor repeat — how does bisection close in on it step by step?"}}],"reveal":{"zh":"对角线长 √2，它在数轴上有确定的位置；不能写成分数，但可用二分法无限逼近，夹在两个越来越近的有理数之间。","en":"The diagonal is √2 long and has an exact place on the number line; it is no fraction, but bisection traps it between rational numbers that draw ever closer."},"source":"../math/arithmetic/real-number-line/#step2","lesson":"real-number-line"},
"q-similarity-scaling-0":{"target":{"node":"similarity-scaling","href":"../math/geometry/similarity-scaling/#step2"},"prompts":[{"node":"similarity-scaling","ask":{"zh":"放大 k 倍，长度、面积、体积各乘几？为什么面积和体积的倍数不一样？","en":"Enlarge by k — lengths, areas and volumes multiply by what? Why are the area and volume factors different?"}},{"node":"pinhole-ratio","ask":{"zh":"照相小孔成像里，物距和像距的比决定放大倍数——放大倍数变了，面积的倍数怎样跟着变？","en":"In pinhole imaging the ratio of object to image distance sets the scale — when the scale changes, how does the area factor follow?"}}],"reveal":{"zh":"长度×k、面积×k²、体积×k³，因为面积是两条边的乘积、体积是三条边的乘积；放大一倍，面积变 4 倍、体积变 8 倍。","en":"Lengths ×k, areas ×k², volumes ×k³, because area multiplies two sides and volume three; doubling the size quadruples area and multiplies volume by eight."},"source":"../math/geometry/similarity-scaling/#step2","lesson":"similarity-scaling"},
"q-simultaneous-equations-0":{"target":{"node":"simultaneous-equations","href":"../math/algebra/simultaneous-equations/#step4"},"prompts":[{"node":"simultaneous-equations","ask":{"zh":"两个一次方程的公共解是两条直线的交点——两条直线相交、平行、重合时，各有几个公共解？","en":"The common solution of two linear equations is where two lines cross — for crossing, parallel and coincident lines, how many common solutions are there?"}},{"node":"slope","ask":{"zh":"直线的斜率不同，相交情况怎样？斜率相同但截距不同呢？","en":"What happens when the lines have different slopes? Same slope but different intercepts?"}}],"reveal":{"zh":"斜率不同必相交于唯一解；斜率相同、截距不同则平行无解；斜率截距都相同则重合，有无穷多解。","en":"Different slopes always cross at exactly one solution; same slope with different intercepts means parallel lines and no solution; same slope and intercept means coincident lines and infinitely many solutions."},"source":"../math/algebra/simultaneous-equations/#step4","lesson":"simultaneous-equations"},
"q-solid-geometry-0":{"target":{"node":"solid-geometry","href":"../math/geometry/solid-geometry/#step2"},"prompts":[{"node":"solid-geometry","ask":{"zh":"平面截立方体，能切出几边形？最多几边？为什么不能切出七边形？","en":"Slicing a cube with a plane, how many sides can the cut have? What is the most, and why not seven?"}},{"node":"integral","ask":{"zh":"切片累加能得到金字塔体积 1/3——把立体切成薄片再加起来，和积分有什么关系？","en":"Stacking slices gives a pyramid's volume as 1/3 — what does adding up thin slices have to do with integration?"}}],"reveal":{"zh":"平面截立方体可得 3、4、5、6 边形，立方体只有 6 个面所以最多 6 边；薄片累加就是积分的思想，金字塔体积是同底同高柱体的 1/3。","en":"A plane cut gives 3, 4, 5 or 6 sides — six faces means six at most; adding thin slices is exactly the idea of integration, and a pyramid's volume is 1/3 of the prism on the same base and height."},"source":"../math/geometry/solid-geometry/#step2","lesson":"solid-geometry"},
"q-three-views-0":{"target":{"node":"three-views","href":"../math/geometry/three-views/#step3"},"prompts":[{"node":"three-views","ask":{"zh":"只看主视图，能确定每格堆了几块吗？","en":"From the front view alone, can you tell how many blocks are stacked in each square?"}},{"node":"vectors","ask":{"zh":"只有两个视图时为什么可能有多种堆法？第三个视图补上了什么信息？","en":"Why can two views leave several possible stackings? What information does the third view add?"}}],"reveal":{"zh":"两个视图只能确定两个方向的位置，高度方向的信息不全；三个视图从三个方向对齐，才能唯一还原立体。","en":"Two views fix positions in only two directions and leave heights underdetermined; three aligned views from three directions pin down the stack uniquely."},"source":"../math/geometry/three-views/#step3","lesson":"three-views"},
"q-compound-interest-0":{"target":{"node":"compound-interest","href":"../investment/rates/compound-interest/#step1"},"prompts":[{"node":"compound-interest","ask":{"zh":"利息也生利息，钱是按加法长还是按倍数长？同样利率，早 10 年和晚 10 年差多少个翻倍周期？","en":"Interest earning interest — does money grow by addition or by multiples? At the same rate, how many doubling periods does starting 10 years earlier buy?"}},{"node":"montecarlo","ask":{"zh":"如果用随机模拟算很多条未来路径，早开始的优势是每次都出现，还是只在平均意义上？","en":"If you simulate many random future paths, does the early starter's advantage show up every time, or only on average?"}}],"reveal":{"zh":"复利按倍数增长 A = P(1+r)ᵗ，时间在指数上，早开始多滚几轮，差距是指数级的；翻倍时间约 72/r 年。","en":"Compound growth multiplies, A = P(1+r)ᵗ, with time in the exponent — starting earlier adds compounding rounds and the gap grows exponentially; doubling takes about 72/r years."},"source":"../investment/rates/compound-interest/#step1","lesson":"compound-interest"},
"q-conic-sections-0":{"target":{"node":"conic-sections","href":"../math/geometry/conic-sections/#step1"},"prompts":[{"node":"conic-sections","ask":{"zh":"平面切圆锥，切的角度不同，截线怎样从圆变到椭圆、抛物线、双曲线？","en":"Cut a cone with a plane at different angles — how does the section change from circle to ellipse to parabola to hyperbola?"}},{"node":"eigen","ask":{"zh":"离心率 e 是到焦点与到准线距离之比——e = 0、e < 1、e = 1、e > 1 各对应哪种曲线？","en":"Eccentricity e is the ratio of distance to focus over distance to directrix — which curve goes with e = 0, e < 1, e = 1, e > 1?"}}],"reveal":{"zh":"它们是同一族曲线：平面切圆锥的角度不同而已，离心率 e 统一定义了四种类型；椭圆距离和、双曲线距离差为定值。","en":"They are one family: the same cone cut at different angles, unified by eccentricity e; an ellipse has constant sum of distances, a hyperbola constant difference."},"source":"../math/geometry/conic-sections/#step1","lesson":"conic-sections"},
"q-counting-permutations-0":{"target":{"node":"counting-permutations","href":"../probability/basics/counting-permutations/#step3"},"prompts":[{"node":"counting-permutations","ask":{"zh":"分步相乘：每步的选择数相乘得到什么？顺序不算数时为什么要除以 k!？","en":"Multiply the choices at each step — what does that give? When order does not matter, why divide by k!?"}},{"node":"probability","ask":{"zh":"等可能时概率 = 符合的方法数 ÷ 总方法数——生日问题里，分子分母各是什么？","en":"With equally likely outcomes, probability = matching counts ÷ total counts — in the birthday problem, what are the numerator and denominator?"}},{"node":"bayes","ask":{"zh":"数出概率后，新证据出现时怎样更新？贝叶斯更新改变的是分子还是分母？","en":"Once you have counted a probability, how does new evidence update it? Does Bayes change the numerator or the denominator?"}}],"reveal":{"zh":"分步相乘数出全部方法，符合条件的方法除以总数就是概率；新证据用贝叶斯规则更新，不用重猜。","en":"Multiply step by step to count all outcomes, divide the matching ones by the total for the probability; new evidence updates it by Bayes' rule, no guessing needed."},"source":"../probability/basics/counting-permutations/#step3","lesson":"counting-permutations"},
"q-expected-value-0":{"target":{"node":"expected-value","href":"../probability/basics/expected-value/#step1"},"prompts":[{"node":"expected-value","ask":{"zh":"期望 E = Σ p·x 算的是什么？净期望（期望 − 价格）怎样判断下注值不值？","en":"What does E = Σ p·x compute? How does net expectation (expectation minus price) judge whether a bet is worth it?"}},{"node":"probability","ask":{"zh":"长期平均为什么是“公平价”？单次结果和长期平均有什么不同？","en":"Why is the long-run average a “fair price”? How does a single outcome differ from the long-run average?"}},{"node":"variance","ask":{"zh":"只看期望会漏掉什么？为什么保险愿意用较差的期望换取更小的波动？","en":"What do you miss if you look only at expectation? Why would insurance trade a worse expectation for a smaller spread?"}}],"reveal":{"zh":"期望是长期平均的公平价，净期望等于期望减价格，E[X+Y] = E[X] + E[Y] 可以直接相加。但期望之外还要看波动，保险正是用较差的期望换取更小的波动。","en":"Expectation is the fair price of a long-run average, net expectation is expectation minus price, and E[X+Y] = E[X] + E[Y] adds directly. But beyond the mean you must also watch the spread — insurance trades a worse expectation for a smaller one."},"source":"../probability/basics/expected-value/#step1","lesson":"expected-value"},
"q-isomers-0":{"target":{"node":"isomers","href":"../chemistry/matter/isomers/#step1"},"prompts":[{"node":"probability","ask":{"zh":"同一分子式可以有不同连接——数烷烃骨架时，怎样避免把同一种结构数两遍？","en":"One formula can connect in different ways — when counting alkane skeletons, how do you avoid counting the same structure twice?"}},{"node":"isomers","ask":{"zh":"醇和醚原子数相同，连接不同——官能团不同，性质会一样吗？","en":"An alcohol and an ether can share the same atoms with different connections — do different functional groups mean different properties?"}},{"node":"molecular-shapes","ask":{"zh":"顺反异构形状不同——形状不同，分子性质和作用会不同吗？","en":"Cis–trans isomers differ in shape — does a different shape mean different properties and behaviour?"}}],"reveal":{"zh":"同样的原子、不同的连接就是不同的分子；骨架、官能团、顺反形状都不同，性质也就不同，计数时要用规范形式去重。","en":"Same atoms with different connections are different molecules; skeleton, functional group and cis–trans shape all change properties, and counting needs canonical forms to avoid duplicates."},"source":"../chemistry/matter/isomers/#step1","lesson":"isomers"},
"q-molecular-shapes-0":{"target":{"node":"molecular-shapes","href":"../chemistry/matter/molecular-shapes/#step0"},"prompts":[{"node":"electric-fields","ask":{"zh":"价层电子对互相排斥——N 个区域怎样排布才最散？孤对为什么“更胖”？","en":"Valence electron pairs repel each other — how do N regions arrange to spread out most? Why are lone pairs \"fatter\"?"}},{"node":"molecular-shapes","ask":{"zh":"水分子有两个孤对——孤对挤压成键对，键角是变大还是变小？变成多少度左右？","en":"Water has two lone pairs — do they squeeze the bonding pairs to a bigger or smaller angle? About how many degrees?"}},{"node":"derivative","ask":{"zh":"形状不对称，水分子就有极性——极性和键角有什么关系？","en":"Water's lopsided shape gives it polarity — how is polarity tied to the bond angle?"}}],"reveal":{"zh":"电子对互斥让四个区域排成四面体，两个孤对更胖、挤压成键对，水就弯成约 104.5°，不对称的形状带来极性。","en":"Repulsion arranges four regions tetrahedrally; the two fatter lone pairs squeeze the bonding pairs, bending water to about 104.5°, and that lopsided shape makes it polar."},"source":"../chemistry/matter/molecular-shapes/#step0","lesson":"molecular-shapes"},
"q-periodic-trends-0":{"target":{"node":"periodic-trends","href":"../chemistry/matter/periodic-trends/#step2"},"prompts":[{"node":"electric-fields","ask":{"zh":"同一周期从左往右，核电荷怎样变？电子层数变吗？","en":"Across a period from left to right, how does the nuclear charge change? Does the number of shells change?"}},{"node":"periodic-trends","ask":{"zh":"有效核电荷越大，对外层电子的吸引越强还是越弱？半径跟着怎样变？","en":"The larger the effective nuclear charge, the stronger or weaker the pull on outer electrons? How does the radius follow?"}},{"node":"molecular-shapes","ask":{"zh":"半径趋势和分子形状有什么关系？原子小了，成键时键长会怎样？","en":"How does the radius trend relate to molecular shape? When atoms are smaller, what happens to bond lengths?"}}],"reveal":{"zh":"同周期核电荷递增、电子层不变，有效核电荷把外层电子拉得更紧，原子半径就越往右越小。","en":"Across a period the nuclear charge rises while shells stay put, so the effective nuclear charge pulls outer electrons tighter and radii shrink toward the right."},"source":"../chemistry/matter/periodic-trends/#step2","lesson":"periodic-trends"},
"q-sequences-series-0":{"target":{"node":"sequences-series","href":"../math/algebra/sequences-series/#step1"},"prompts":[{"node":"slope","ask":{"zh":"等差数列倒序相加是把两列拼成长方形——这个办法为什么能一次算出前 n 项和？","en":"Adding an arithmetic series backwards pairs two rows into a rectangle — why does that give the sum of the first n terms at once?"}},{"node":"sequences-series","ask":{"zh":"等比数列 |r|<1 时部分和趋近极限——公比小于 1 时，后面的项是变大还是变小？小到什么程度？","en":"For a geometric series with |r| < 1 the partial sums approach a limit — with ratio below 1, do later terms grow or shrink? How small do they get?"}},{"node":"integral","ask":{"zh":"无穷项求和与积分有什么相通处？线性累计和指数累计的反超说明了什么？","en":"What does summing infinitely many terms share with integration? What does linear versus exponential accumulation overtaking tell us?"}}],"reveal":{"zh":"|r|<1 时后面的项趋近于 0，部分和收敛到有限值；等比增长最终会反超线性增长，这就是无穷求和有结果的道理。","en":"With |r| < 1 later terms shrink toward zero and partial sums converge to a finite value; exponential growth eventually overtakes linear growth — that is how infinitely many terms can add up to something."},"source":"../math/algebra/sequences-series/#step1","lesson":"sequences-series"},
"q-vectors-0":{"target":{"node":"vectors","href":"../math/linear-algebra/vectors/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"向量加法首尾相接——两个力方向相同、相反时，合力各是多少？","en":"Vector addition joins arrows head to tail — for two forces in the same direction, and in opposite directions, what is each resultant?"}},{"node":"net-force","ask":{"zh":"绳子受力平衡时，几个力的合力是多少？合力为零意味着什么？","en":"When rope forces balance, what is their resultant? What does a zero resultant mean?"}}],"reveal":{"zh":"力按矢量相加：首尾相接画箭头，合力是起点到终点的箭头；合力为零就是平衡。","en":"Forces add as vectors: join arrows head to tail and the resultant runs from start to finish; a zero resultant is balance."},"source":"../math/linear-algebra/vectors/#step1","lesson":"vectors"},
"q-embeddings-0":{"target":{"node":"embeddings","href":"../computing/ml/embeddings/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"词表示成一列数——余弦衡量相似，余弦接近 1 说明什么？","en":"Words become lists of numbers — cosine measures similarity; what does a cosine near 1 say?"}},{"node":"embeddings","ask":{"zh":"向量加减做类比——“国王 − 男人 + 女人”会指向什么？","en":"Vector arithmetic solves analogies — what does “king − man + woman” point at?"}},{"node":"attention-mechanism","ask":{"zh":"从共现统计里学出向量——经常一起出现的词，向量会靠近还是远离？","en":"Vectors are learned from co-occurrence statistics — do words that often appear together end up closer or farther apart?"}}],"reveal":{"zh":"共现统计把词变成向量，余弦度量相似、加减法做类比；注意力机制正是用这些向量算查询与键的点积。","en":"Co-occurrence statistics turn words into vectors, cosine measures similarity and arithmetic solves analogies; the attention mechanism then uses these vectors for query-key dot products."},"source":"../computing/ml/embeddings/#step1","lesson":"embeddings"},
"q-externalities-0":{"target":{"node":"externalities","href":"../math/applied/externalities/#step3"},"prompts":[{"node":"externalities","ask":{"zh":"价格漏掉一部分成本时，市场会多生产还是少生产？无谓损失 ½·e·(Q_m − Q*) 里每个字母是什么意思？","en":"When the price leaves out part of the cost, does the market produce too much or too little? In the deadweight loss ½·e·(Q_m − Q*), what does each letter mean?"}},{"node":"supply-demand","ask":{"zh":"均衡价格是两边都愿意交易的交点——如果成本没进价格，这个交点还对吗？","en":"The equilibrium price is where both sides plan to trade — if the cost never entered the price, is that crossing point still right?"}},{"node":"game-theory","ask":{"zh":"公地悲剧为什么是多人博弈？每个人都理性时，为什么结果反而对大家都不好？","en":"Why is the tragedy of the commons a many-player game? When everyone is rational, why is the outcome worse for all?"}}],"reveal":{"zh":"部分成本落在第三方身上时，市场按私人成本多生产，无谓损失等于 ½·e·(Q_m − Q*)。庇古税按边际外部损害定价可使福利最大，而科斯指出无成本谈判下权利归谁不影响效率。","en":"When part of the cost falls on a third party the market over-produces on private cost, with deadweight loss ½·e·(Q_m − Q*). A Pigouvian tax equal to the marginal damage maximises welfare, and Coase notes that with costless bargaining who holds the rights does not change efficiency."},"source":"../math/applied/externalities/#step3","lesson":"externalities"},
"q-linear-transform-0":{"target":{"node":"determinant","href":"../math/linear-algebra/linear-transform/#step2"},"prompts":[{"node":"determinant","ask":{"zh":"单位正方形被矩阵变成了什么形状？它的面积是多少，为什么会有负号？","en":"What shape does the matrix turn the unit square into? What is its area, and why can it be negative?"}},{"node":"matrix-transform","ask":{"zh":"两根基向量的像共线时，平面会被压成什么？还能从结果唯一找回原来的点吗？","en":"If the two basis vectors land on one line, what does the plane collapse to? Can the original point still be recovered uniquely?"}}],"reveal":{"zh":"行列式是矩阵把面积放大的倍数，带符号：负号表示翻面。等于 0 时整个平面被压到一条线（或一点）上，许多不同的点落到同一个结果，信息丢了，自然没有逆矩阵。","en":"The determinant is the factor by which the matrix scales area, with a sign: negative means the plane is flipped. When it is 0 the whole plane is squashed onto a line (or a point), many points share one image, information is lost, and so there is no inverse."},"source":"../math/linear-algebra/linear-transform/#step2","lesson":"linear-transform"},
"q-newton-method-0":{"target":{"node":"newton-method","href":"../math/calculus/newton-method/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"用切线与横轴的交点作下一个猜测——为什么切线交点比原点更接近根？","en":"Take where the tangent meets the x-axis as the next guess — why is the tangent's crossing closer to the root than the starting point?"}},{"node":"newton-method","ask":{"zh":"正确位数大约翻倍——这比二分法快多少？切线水平、循环时又会怎样失败？","en":"Correct digits roughly double — how much faster is that than bisection? And how does it fail with a flat tangent or a cycle?"}}],"reveal":{"zh":"切线在根附近是很好的近似，交点一次比一次准、正确位数约翻倍；但切线水平、循环或起点不好时也会失败，这时二分法更稳。","en":"Near the root the tangent is a good approximation, so each crossing lands closer and correct digits roughly double; but a flat tangent, a cycle or a bad start can break it, where bisection stays steady."},"source":"../math/calculus/newton-method/#step2","lesson":"newton-method"},
"q-pagerank-0":{"target":{"node":"pagerank","href":"../computing/algorithms/pagerank/#step2"},"prompts":[{"node":"probability","ask":{"zh":"“重要”定义成随机冲浪者长期停留的概率——被很多页链接的页，停留概率一定高吗？","en":"“Important” means the long-run probability of a random surfer — does a page with many incoming links necessarily have a high stay probability?"}},{"node":"pagerank","ask":{"zh":"阻尼系数是什么意思？冲浪者为什么有时要随机跳到任意一页？","en":"What is the damping factor? Why does the surfer sometimes jump to a random page?"}},{"node":"eigen","ask":{"zh":"幂迭代怎样算出这个长期概率？它和特征向量有什么关系？","en":"How does power iteration compute that long-run probability? What does it have to do with an eigenvector?"}}],"reveal":{"zh":"重要不只看链接数，还看链接来自谁；随机冲浪者的长期停留概率就是 PageRank，幂迭代算出的正是它的特征向量。","en":"Importance is not just link count but who links to you; the random surfer's long-run stay probability is PageRank, and power iteration computes exactly its eigenvector."},"source":"../computing/algorithms/pagerank/#step2","lesson":"pagerank"},
"q-rsa-encryption-0":{"target":{"node":"rsa-encryption","href":"../computing/systems/rsa-encryption/#step3"},"prompts":[{"node":"exp-log","ask":{"zh":"位数每加 1，试除的步数为什么乘 10？指数增长在这里意味着什么？","en":"Why does one more digit multiply trial-division work by ten? What does exponential growth mean here?"}},{"node":"rsa-encryption","ask":{"zh":"质数相乘易、分解难，怎样变成公钥和私钥？欧拉定理在其中起什么作用？","en":"How does “multiplying primes is easy, factoring is hard” become a public and a private key? What role does Euler's theorem play?"}},{"node":"hashing","ask":{"zh":"单向函数是什么意思？为什么哈希和 RSA 都依赖它？","en":"What is a one-way function? Why do both hashing and RSA rely on one?"}}],"reveal":{"zh":"质数相乘易、分解难，模算术、欧拉定理与扩展欧几里得算法造出公钥和私钥，加密解密对所有明文成立。窃听者只能试除，而位数每加 1 步数乘 10，现实密钥长度让试除不可行。","en":"Multiplying primes is easy and factoring is hard, so modular arithmetic, Euler's theorem and the extended Euclidean algorithm build a public and a private key for which encryption and decryption hold for every message. An eavesdropper can only trial-divide, and one more digit means ten times the work, so real key lengths make it infeasible."},"source":"../computing/systems/rsa-encryption/#step3","lesson":"rsa-encryption"},
"q-taylor-series-0":{"target":{"node":"taylor-series","href":"../math/calculus/taylor-series/#step2"},"prompts":[{"node":"derivative","ask":{"zh":"系数来自各阶导数——在一点处让多项式和函数各阶导数都相等，近处会贴合吗？","en":"Coefficients come from derivatives of each order — matching a polynomial's derivatives to the function's at one point: does it fit nearby?"}},{"node":"taylor-series","ask":{"zh":"收敛半径内加项变准、半径外越加越差——对 ln(1+x)，半径是多少？","en":"Inside the radius of convergence more terms mean more accuracy, outside it worse — for ln(1+x), what is the radius?"}},{"node":"fourier","ask":{"zh":"泰勒是局部逼近，傅里叶是整体逼近——两者各适合什么场景？","en":"Taylor approximates locally, Fourier globally — which scenes suit each?"}}],"reveal":{"zh":"在一点处逐项贴合各阶导数，近处多项式就和函数几乎重合；收敛半径内加项变准，半径外反而变差；傅里叶则是用正弦波在整体上逼近。","en":"Matching derivatives term by term at one point makes the polynomial nearly coincide nearby; inside the radius more terms help, outside they hurt; Fourier instead approximates globally with sine waves."},"source":"../math/calculus/taylor-series/#step2","lesson":"taylor-series"}
}});
